// Bundle individual .d.ts files into a single index.d.ts
// Reads tsc --emitDeclarationOnly output and wraps in namespace blocks
var fs = require('fs');
var path = require('path');

var ROOT = __dirname + '/..';

var PACKAGES = [
  { name: 'core', nsForFile: function(rel) { return 'egret'; } },
  { name: 'eui', nsForFile: function(rel) {
    if (rel.includes('extension\\eui') || rel.includes('extension/eui')) return 'eui';
    return 'egret';
  }},
  { name: 'game', nsForFile: function(rel) {
    if (rel.includes('extension\\game') || rel.includes('extension/game')) return 'game';
    return 'egret';
  }},
  { name: 'tween', nsForFile: function(rel) {
    if (rel.includes('extension\\tween') || rel.includes('extension/tween')) return 'tween';
    return 'egret';
  }},
  { name: 'socket', nsForFile: function(rel) {
    if (rel.includes('extension\\socket') || rel.includes('extension/socket')) return 'socket';
    return 'egret';
  }},
];

function walkDts(dir) {
  var results = [];
  if (!fs.existsSync(dir)) return results;
  var entries = fs.readdirSync(dir, { withFileTypes: true });
  for (var i = 0; i < entries.length; i++) {
    var p = path.join(dir, entries[i].name);
    if (entries[i].isDirectory()) {
      results = results.concat(walkDts(p));
    } else if (entries[i].isFile() && p.endsWith('.d.ts')) {
      results.push(p);
    }
  }
  return results;
}

function convertToNamespace(content) {
  // Remove import statements (everything will be in one namespace)
  content = content.replace(/^import\s+type\s+.*$/gm, '');
  content = content.replace(/^import\s+\{.*?\}\s+from\s+["'][^"']+["'];?\s*$/gm, '');
  content = content.replace(/^import\s+\*\s+as\s+\w+\s+from\s+["'][^"']+["'];?\s*$/gm, '');
  content = content.replace(/^import\s+["'][^"']+["'];?\s*$/gm, '');
  
  // Remove sourceMappingURL
  content = content.replace(/^\/\/# sourceMappingURL.*$/gm, '');
  
  // Remove 'export' keyword from declarations (they become namespace members)
  // But keep export in 'export declare' and 'export class' etc.
  content = content.replace(/^export\s+(default\s+)?/gm, '');

  // Remove empty lines at start/end
  content = content.trim();
  
  return content;
}

function bundleDts(pkg) {
  var distDir = path.join(ROOT, 'packages', pkg.name, 'dist');
  
  // First, generate individual .d.ts using tsc
  console.log('  Running tsc --emitDeclarationOnly for ' + pkg.name + '...');
  
  // Clean old d.ts files (except index.d.ts which we'll overwrite)
  var oldDtsFiles = walkDts(distDir).filter(function(f) { return !f.endsWith('index.d.ts'); });
  oldDtsFiles.forEach(function(f) { try { fs.unlinkSync(f); } catch(e) {} });
  
  // Don't run tsc here - assume it was already run
  // Instead, just bundle
  
  var dtsFiles = walkDts(distDir).filter(function(f) {
    // Skip index.d.ts, _entry.d.ts (these are our output)
    var basename = path.basename(f);
    return basename !== 'index.d.ts' && basename !== '_entry.d.ts';
  });

  if (dtsFiles.length === 0) {
    console.log('  No .d.ts files found in ' + distDir + ' (run tsc --emitDeclarationOnly first)');
    return;
  }

  // Group by namespace
  var nsBlocks = {};
  for (var i = 0; i < dtsFiles.length; i++) {
    var rel = path.relative(distDir, dtsFiles[i]);
    var ns = pkg.nsForFile(rel);
    
    var content = fs.readFileSync(dtsFiles[i], 'utf8');
    var converted = convertToNamespace(content);
    
    if (converted) {
      if (!nsBlocks[ns]) nsBlocks[ns] = [];
      nsBlocks[ns].push('// ' + rel + '\n' + converted);
    }
  }

  // Build final d.ts
  var dts = '// Type definitions for @egret-r\n';
  dts += '// Auto-generated by tsc --emitDeclarationOnly. Do not edit.\n\n';

  if (pkg.name !== 'core') {
    dts += "import { egret } from '@egret-r/core';\n\n";
  }

  // Determine namespaces present
  var allNs = Object.keys(nsBlocks);
  
  // Write namespace blocks
  for (var n = 0; n < allNs.length; n++) {
    var ns = allNs[n];
    if (nsBlocks[ns] && nsBlocks[ns].length > 0) {
      dts += 'declare namespace ' + ns + ' {\n';
      dts += nsBlocks[ns].join('\n\n');
      dts += '\n}\n\n';
    }
  }

  dts += 'export as namespace egret;\n';
  
  if (allNs.length > 0) {
    dts += '\nexport { ' + allNs.join(', ') + ' };\n';
  }

  var outPath = path.join(distDir, 'index.d.ts');
  fs.writeFileSync(outPath, dts, 'utf8');
  
  // Clean up individual d.ts files (keep only index.d.ts)
  dtsFiles.forEach(function(f) { try { fs.unlinkSync(f); } catch(e) {} });
  try { fs.unlinkSync(path.join(distDir, '_entry.d.ts')); } catch(e) {}
  try { fs.unlinkSync(path.join(distDir, '_entry.d.ts.map')); } catch(e) {}

  var size = fs.statSync(outPath).size;
  console.log('  ' + pkg.name + ': ' + size.toLocaleString() + ' bytes (' + dtsFiles.length + ' source files)');
}

console.log('Bundling .d.ts files...\n');

// First run tsc for each package
for (var i = 0; i < PACKAGES.length; i++) {
  var pkg = PACKAGES[i];
  var pkgDir = path.join(ROOT, 'packages', pkg.name);
  
  console.log('  Compiling ' + pkg.name + ' declarations...');
  var execSync = require('child_process').execSync;
  try {
    execSync('npx tsc --declaration --emitDeclarationOnly --outDir dist 2>&1', { 
      cwd: pkgDir, 
      stdio: 'pipe',
      timeout: 60000
    });
  } catch(e) {
    // tsc may report errors but still emit declarations
    console.log('    (tsc reported errors, checking output...)');
  }
  
  bundleDts(pkg);
}

console.log('\nDone!');
